import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
const path = 'docs/engineering/playability-launch-review/evidence/p14b4-20260919/914-c2rm-legacy-selection.json'
const raw = readFileSync(path)
const sha = value => createHash('sha256').update(value).digest('hex')
assert.equal(sha(raw), 'aa0a45521227f87ae0251fa0c859504956a46a3bdaa0a5088cbd79e80bfc6bd5')
const original = JSON.parse(raw.toString('utf8'))
const excluded = ['tests/bridge-p14c2b-extension.test.ts', 'tests/bridge-p14b8-waiver-surface.test.ts']
const files = original.files.filter(path => !excluded.includes(path))
assert.equal(files.length, 30)
const extra = [
  'F11 preserves command member-only directorId and nullable base use',
  'F12 emits six concrete Production-state fixture members without promoting conflicts',
  'pins exact positive output identities and deterministic rerendering',
  'keeps checked-in JSON and generated C# byte-derived from the canonical schema',
]
const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
const pattern = original.testNamePattern + '|' + extra.map(name => '(?:^| )' + escape(name) + '$').join('|')
const args = ['run', '--project', 'core', ...files, '--testNamePattern', pattern]
console.log(JSON.stringify({ files, testNamePattern: pattern, excluded, reuse: 'B8 whole-file unchanged observation1046; C2b W10 previously qualified', command: ['node_modules/.bin/vitest', ...args] }))
const child = spawnSync('node_modules/.bin/vitest', args, { stdio: 'inherit' })
assert.equal(sha(readFileSync(path)), sha(raw), 'selector manifest changed')
if (child.error) throw child.error
if (child.signal) throw new Error('Vitest terminated by ' + child.signal)
process.exitCode = child.status ?? 1
